package day02;

public class Program02_TypeCasting {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		//Down casting or Explicit type conversion
		float height=162.5f;
		int heightInt=(int)height;
		System.out.println(heightInt);
		
		//Up casting or Implicit type conversion
		int age=32;
		float ageFloat=age;
		System.out.println(ageFloat);
		
		
	}

}